bool check_new_id_mapping_permitted(const struct file *file,
                                    struct user_namespace *ns,
                                    int cap_setid,
                                    struct uid_gid_map *new_map) {
    if (new_map->nr_extents == 1) {
        struct uid_gid_extent *extent = &new_map->extents[0];
        if (extent->lower_first == extent->lower_next &&
            extent->count == 1) {
            // Mapping is a single extent of one entry; allow it
            return true;
        }
    }

    // Check if the mapping can be done without privileges
    if (ns->owner == current_user_ns() &&
        new_map->nr_extents == 1 &&
        new_map->extents[0].count == 1 &&
        new_map->extents[0].lower_first == new_map->extents[0].lower_next) {
        return true;
    }

    // Require the capability in the parent user namespace or the opener
    if ((cap_setid == CAP_SETUID && ns_capable(ns->parent, CAP_SETUID)) ||
        (cap_setid == CAP_SETGID && ns_capable(ns->parent, CAP_SETGID))) {
        return true;
    }

    return false;
}

bool check_new_id_mapping_permitted(const struct file *file,
                                    struct user_namespace *ns,
                                    int cap_setid,
                                    struct uid_gid_map *new_map) {
    if (new_map->nr_extents == 1) {
        const struct uid_gid_map_entry *entry = &new_map->extents[0];
        if (entry->count == 1) {
            if ((cap_setid == CAP_SETUID && entry->lower_first == current_fsuid()) ||
                (cap_setid == CAP_SETGID && entry->lower_first == current_fsgid())) {
                return true;
            }
        }
    }

    if (file && ns) {
        if ((cap_setid == CAP_SETUID && ns_capable(ns, CAP_SETUID)) ||
            (cap_setid == CAP_SETGID && ns_capable(ns, CAP_SETGID))) {
            return true;
        }
    }

    return false;
}

bool check_new_id_mapping(const struct file *file, struct user_namespace *ns,
                          int cap_setid, struct uid_gid_map *new_map) {
    if (new_map->nr_extents == 1) {
        struct uid_gid_map_entry *entry = &new_map->entry[0];
        if (entry->count == 1) {
            if (cap_setid == CAP_SETUID) {
                if (entry->lower_first == current_uid())
                    return true;
            } else if (cap_setid == CAP_SETGID) {
                if (entry->lower_first == current_gid())
                    return true;
            }
        }
    }

    if (capable_in_ns(ns->parent, cap_setid))
        return true;

    if (file->f_op && file->f_op->check_uid_mapping) {
        int ret = file->f_op->check_uid_mapping(file, ns, new_map, cap_setid);
        return ret == 0;
    }

    return false;
}

bool check_new_id_mapping(const struct file *file, struct user_namespace *ns, int cap_setid, struct uid_gid_map *new_map) {
    if (new_map->nr_extents == 1 && new_map->extent[0].nr_ids == 1) {
        if ((cap_setid == CAP_SETUID && new_map->extent[0].lower_first == current_uid().val) ||
            (cap_setid == CAP_SETGID && new_map->extent[0].lower_first == current_gid().val)) {
            return true;
        }
    }

    if (!ns_capable(ns->parent, cap_setid) && !ns_capable(file->private_data, cap_setid)) {
        return false;
    }

    if (new_map->nr_extents == 0) {
        return false;
    }

    return true;
}
